const result = estados_cidades_coord.map(cid => estados.map(est => est.nome === cid.admin_name) && {
  ...cid,
  sigla_state: estados.find(est => est.nome === cid.admin_name && est.sigla).sigla
})

var fileName = `${"dados"}.json`;
// Create a blob of the data
var fileToSave = new Blob([JSON.stringify(result)], {
  type: 'application/json'
});
// Save the file
saveAs(fileToSave, fileName);
